      "Daily writing exercise": "Codzienne ćwiczenie pisania",
      "Daily speaking practice": "Codzienna praktyka mówienia",
      "Daily presentation practice": "Codzienna praktyka prezentacji",
      "Our platform is designed to make practicing reading, writing, and speaking both effective and engaging. We draw on proven scientific research to create activities that strengthen the brain, build confidence, and support lifelong learning.":
          "Nasza platforma została zaprojektowana tak, aby praktyka czytania, pisania i mówienia była zarówno skuteczna, jak i angażująca. Opieramy się na sprawdzonych badaniach naukowych, aby tworzyć działania, które wzmacniają mózg, budują pewność siebie i wspierają uczenie się przez całe życie.",
      "Real-Time Analytics": "Analityka w czasie rzeczywistym",
      "Built with cognitive science principles and tested with dyslexia specialists":
          "Zbudowany w oparciu o zasady nauk poznawczych i przetestowany ze specjalistami od dysleksji",
      "Advanced AI Technology": "Zaawansowana technologia AI",
      "Machine learning adapts to individual learning patterns and preferences":
          "Uczenie maszynowe dostosowuje się do indywidualnych wzorców uczenia się i preferencji",
      "Passion-Driven Learning": "Nauka oparta na pasji",
      "Connect education with personal interests for maximum engagement":
          "Połącz edukację z osobistymi zainteresowaniami dla maksymalnego zaangażowania",
      "100,000+ Learners": "100 000+ uczniów",
      "Positive Rating": "Pozytywna ocena",
      "AI Support": "Wsparcie AI",
      "At the Core of Our Approach are": "U podstaw naszego podejścia leżą",
      "4 Key Foundations": "4 kluczowe fundamenty",
      "1. Neuroplasticity": "1. Neuroplastyczność",
      "The brain has an incredible ability to reorganize itself by forming new neural connections throughout life. This process not only supports learning and problem-solving but also helps individuals adapt to new challenges. Our activities are designed to activate neuroplasticity, making practice more impactful over time.":
          "Mózg ma niesamowitą zdolność do reorganizacji poprzez tworzenie nowych połączeń neuronowych przez całe życie. Proces ten nie tylko wspiera naukę i rozwiązywanie problemów, ale także pomaga jednostkom dostosować się do nowych wyzwań. Nasze działania mają na celu aktywację neuroplastyczności, dzięki czemu praktyka staje się bardziej skuteczna z upływem czasu.",
      "2. Rhythmic Therapy": "2. Terapia rytmiczna",
      "Humans are naturally responsive to rhythm. By using rhythmic and repetitive patterns, we help regulate the brain and nervous system. Here, we use music to rhythmically influence the reshaping of neurons and their plasticity by creating new neuronic pathways when working on our activities.This fortifies retention and facilitates the application of newly learned behaviors when using cognitive processing. This approach can reduce stress, improve focus, and create a natural flow in reading, writing, and speaking.":
          "Ludzie naturalnie reagują na rytm. Poprzez stosowanie rytmicznych i powtarzalnych wzorców pomagamy regulować pracę mózgu i układu nerwowego. Tutaj używamy muzyki, aby rytmicznie wpływać na kształtowanie neuronów i ich plastyczność poprzez tworzenie nowych ścieżek neuronowych podczas pracy nad naszymi działaniami. Wzmacnia to zapamiętywanie i ułatwia stosowanie nowo nabytej wiedzy podczas procesów poznawczych. Podejście to może zmniejszyć stres, poprawić koncentrację i stworzyć naturalny przepływ w czytaniu, pisaniu i mówieniu.",
      "3. Dysgraphia Support": "3. Wsparcie dla osób z dysgrafią",
      "Dysgraphia is a neurological condition that affects writing. Our tools offer structured practice to strengthen handwriting, written expression, and the motor skills that support the writing process.":
          "Dysgrafia to stan neurologiczny, który wpływa na pisanie. Nasze narzędzia oferują ustrukturyzowaną praktykę mającą na celu wzmocnienie pisma ręcznego, ekspresji pisemnej oraz umiejętności motorycznych wspierających proces pisania.",
      "4. Dyslexia Support": "4. Wsparcie dla osób z dysleksją",
      "Dyslexia, a neurobiological learning difference, can make reading, writing, and spelling difficult. We provide engaging activities that build fluency, comprehension, and language skills—helping learners overcome barriers with confidence.":
          "Dysleksja, neurobiologiczna różnica w uczeniu się, może utrudniać czytanie, pisanie i literowanie. Zapewniamy angażujące działania, które budują biegłość, rozumienie i umiejętności językowe — pomagając uczniom pokonywać bariery z pewnością siebie.",
      "Last Updated: January 21, 2026":
          "Ostatnia aktualizacja: 21 stycznia 2026 r.",
      "At MANIFEX, we respect and value your privacy. This Privacy Policy explains how we collect, use, and protect your personal information when you visit our website or use our services. By accessing MANIFEX, you agree to the practices described in this policy. If you do not agree, please discontinue using our services.":
          "W MANIFEX szanujemy i cenimy Twoją prywatność. Niniejsza Polityka Prywatności wyjaśnia, w jaki sposób gromadzimy, wykorzystujemy i chronimy Twoje dane osobowe podczas odwiedzania naszej strony internetowej lub korzystania z naszych usług. Uzyskując dostęp do MANIFEX, zgadzasz się na praktyki opisane w niniejszej polityce. Jeśli się nie zgadzasz, prosimy o zaprzestanie korzystania z naszych usług.",
      "When you create an account or use MANIFEX, we may collect certain personal information such as your name, email address, age group, language preference, subscription details, and any content you submit during practice activities such as writing exercises. For minors, we may also collect guardian or parent contact details for verification and progress tracking. In addition, we automatically collect certain technical information such as your browser type, device, IP address, and usage activity to ensure smooth functionality and improve the user experience.":
          "Kiedy tworzysz konto lub korzystasz z MANIFEX, możemy gromadzić pewne dane osobowe, takie jak imię i nazwisko, adres e-mail, grupa wiekowa, preferencje językowe, szczegóły subskrypcji oraz wszelkie treści przesyłane podczas ćwiczeń, takie jak zadania pisemne. W przypadku osób niepełnoletnich możemy również gromadzić dane kontaktowe opiekuna lub rodzica w celu weryfikacji i śledzenia postępów. Ponadto automatycznie gromadzimy pewne informacje techniczne, takie jak typ przeglądarki, urządzenie, adres IP i aktywność użytkowania, aby zapewnić sprawne funkcjonowanie i poprawić wrażenia użytkownika.",
      "We use the information we collect to deliver and personalize our services, provide AI-powered feedback, provide subscription payments securely through Stripe, track progress and generate analytics, send user updates or notifications, and improve MANIFEX by analyzing learner behaviors and preferences. Your personal data is used solely for the purpose of operating and enhancing the platform. We never sell your data to third parties.":
          "Wykorzystujemy gromadzone informacje w celu dostarczania i personalizowania naszych usług, zapewniania opinii opartych na sztucznej inteligencji, bezpiecznego przetwarzania płatności za subskrypcję za pośrednictwem Stripe, śledzenia postępów i generowania analityki, wysyłania aktualizacji lub powiadomień użytkownikom oraz ulepszania MANIFEX poprzez analizę zachowań i preferencji uczniów. Twoje dane osobowe są wykorzystywane wyłącznie w celu obsługi i ulepszania platformy. Nigdy nie sprzedajemy Twoich danych stronom trzecim.",
      "MANIFEX uses trusted third-party tools and services, such as Stripe for payment processing. Stripe collects and processes payment information on our behalf, and we do not store your full payment card details on our servers. Integrations with third-party providers are carefully selected, and we require them to follow strict security and privacy practices.":
          "MANIFEX korzysta z zaufanych narzędzi i usług stron trzecich, takich jak Stripe do przetwarzania płatności. Stripe gromadzi i przetwarza informacje o płatnościach w naszym imieniu, a my nie przechowujemy pełnych danych karty płatniczej na naszych serwerach. Integracje z dostawcami zewnętrznymi są starannie dobierane i wymagamy od nich przestrzegania ścisłych praktyk bezpieczeństwa i prywatności.",
      "We take the security of your information seriously. All data is protected using industry-standard encryption and secure storage practices. Access to personal data is restricted to authorized team members only, and we routinely monitor and update our systems to prevent unauthorized access, loss, misuse, or disclosure. However, no system can ever be 100% secure, and we cannot guarantee absolute protection of your information.":
          "Poważnie traktujemy bezpieczeństwo Twoich informacji. Wszystkie dane są chronione przy użyciu standardowych w branży praktyk szyfrowania i bezpiecznego przechowywania. Dostęp do danych osobowych jest ograniczony wyłącznie do upoważnionych członków zespołu, a my rutynowo monitorujemy i aktualizujemy nasze systemy, aby zapobiec nieautoryzowanemu dostępowi, utracie, niewłaściwemu użyciu lub ujawnieniu. Żaden system nie może jednak zagwarantować 100% bezpieczeństwa i nie możemy zagwarantować absolutnej ochrony Twoich danych.",
      "If you are a child or minor, guardian or parent consent may be required to create an account and access certain features. Parent dashboards and notifications may be used to update guardians about a child’s learning progress.":
          "W przypadku dzieci lub osób niepełnoletnich do utworzenia konta i dostępu do niektórych funkcji może być wymagana zgoda opiekuna lub rodzica. Panele rodzicielskie i powiadomienia mogą być używane do informowania opiekunów o postępach w nauce dziecka.",
      "You have certain rights regarding your personal information. At any time, you may access your account, update or correct your details, or request account deletion. If you cancel your subscription or deactivate your account, some data may remain in backup storage or logs but will not be used further. To exercise these rights, please contact us at the provided email address.":
          "Masz określone prawa dotyczące swoich danych osobowych. W dowolnym momencie możesz uzyskać dostęp do swojego konta, zaktualizować lub poprawić swoje dane lub poprosić o usunięcie konta. Jeśli anulujesz subskrypcję lub zdezaktywujesz konto, niektóre dane mogą pozostać w pamięci zapasowej lub logach, ale nie będą dalej wykorzystywane. Aby skorzystać z tych praw, prosimy o kontakt pod podanym adresem e-mail.",
      "Our services are not designed to collect sensitive personal data such as racial or ethnic origin, political opinions, religious beliefs, or health-related details. Please do not provide this information when using our platform.":
          "Nasze usługi nie są zaprojektowane do gromadzenia wrażliwych danych osobowych, takich jak pochodzenie rasowe lub etniczne, opinie polityczne, przekonania religijne lub szczegóły dotyczące zdrowia. Prosimy nie podawać tych informacji podczas korzystania z naszej platformy.",
      "We may update this Privacy Policy from time to time to reflect new features, technologies, or legal requirements. If there are significant changes, we will notify you via email or through the platform. By continuing to use MANIFEX after those updates, you agree to the revised Privacy Policy.":
          "Możemy od czasu do czasu aktualizować niniejszą Politykę Prywatności, aby odzwierciedlić nowe funkcje, technologie lub wymogi prawne. W przypadku istotnych zmian powiadomimy Cię o tym za pośrednictwem poczty elektronicznej lub platformy. Kontynuując korzystanie z MANIFEX po wprowadzeniu tych aktualizacji, zgadzasz się na zmienioną Politykę Prywatności.",
      "This Privacy Policy is governed by the laws of [Insert Country/Region]. Any disputes will be resolved in the courts of [Insert Location].":
          "Niniejsza Polityka Prywatności podlega prawu [Wstaw Kraj/Region]. Wszelkie spory będą rozstrzygane przez sądy w [Wstaw Lokalizację].",
      "If you have any questions, concerns, or complaints about how we handle your personal data, please reach out to us at:\nEmail: [support@manifex.org]\nAddress: [Insert Business Address]":
          "Jeśli masz jakiekolwiek pytania, wątpliwości lub skargi dotyczące sposobu obchodzenia się z Twoimi danymi osobowymi, prosimy o kontakt pod adresem:\nE-mail: [support@manifex.org]\nAdres: [Wstaw adres firmy]",
      "By using MANIFEX, you acknowledge that you have read, understood, and agreed to this Privacy Policy.":
          "Korzystając z MANIFEX, potwierdzasz, że przeczytałeś, zrozumiałeś i zgodziłeś się na niniejszą Politykę Prywatności.",
      "Terms of Conditions": "Regulamin",
      "Welcome to MANIFEX. These Terms of Use (“Terms”) govern your access to and use of our platform, website, and services. By using MANIFEX, you agree to follow these Terms. Please read them carefully. If you do not agree, you may not use our Service.":
          "Witamy w MANIFEX. Niniejszy Regulamin Korzystania („Regulamin”) reguluje dostęp do naszej platformy, strony internetowej i usług oraz korzystanie z nich. Korzystając z MANIFEX, zgadzasz się przestrzegać niniejszego Regulaminu. Przeczytaj go uważnie. Jeśli się nie zgadzasz, nie możesz korzystać z naszego Serwisu.",
      "MANIFEX is intended for learners of all ages, but you must be at least 13 years old to create an account. If you are under 18, you must have parent or guardian consent to use the platform. By using the Service, you confirm that the information you provide is accurate and truthful. When you create an account, you are responsible for safeguarding your password and account. You should notify us immediately if you suspect unauthorized access. We are not liable for damages or losses resulting from failure to protect your login details.":
          "MANIFEX jest przeznaczony dla uczących się w każdym wieku, ale musisz mieć co najmniej 13 lat, aby założyć konto. Jeśli masz mniej niż 18 lat, musisz mieć zgodę rodzica lub opiekuna na korzystanie z platformy. Korzystając z Serwisu, potwierdzasz, że podane przez Ciebie informacje są dokładne i zgodne z prawdą. Tworząc konto, jesteś odpowiedzialny za ochronę swojego hasła i konta. Należy niezwłocznie powiadomić nas o podejrzeniu nieautoryzowanego dostępu. Nie ponosimy odpowiedzialności za szkody lub straty wynikające z niezabezpieczenia danych logowania.",
      "Our platform is designed to help users practice English reading, writing, and speaking through AI-powered support. You agree to use the Service only for learning purposes in a lawful way. Misuse, such as attempting unauthorized access, copying or redistributing content without permission, uploading inappropriate, offensive or illegal material, or disrupting service operations, is prohibited.":
          "Nasza platforma została zaprojektowana, aby pomóc użytkownikom ćwiczyć czytanie, pisanie i mówienie po angielsku dzięki wsparciu sztucznej inteligencji. Zgadzasz się korzystać z Serwisu wyłącznie w celach edukacyjnych w sposób zgodny z prawem. Niewłaściwe użytkowanie, takie jak próba nieautoryzowanego dostępu, kopiowanie lub redystrybucja treści bez pozwolenia, przesyłanie nieodpowiednich, obraźliwych lub nielegalnych materiałów lub zakłócanie działania serwisu, jest zabronione.",
      "Certain features of MANIFEX require a paid subscription. By subscribing, you authorize us to charge your selected payment method through Stripe, our secure payment partner. Subscription fees are displayed on our Pricing page, processed automatically according to your billing cycle, and may renew monthly or annually until canceled. Unless required by law, subscription fees are non-refundable once charged, though in exceptional cases such as duplicate payments or system errors you may contact support for assistance. A free trial, if provided, will be limited to the duration stated.":
          "Niektóre funkcje MANIFEX wymagają płatnej subskrypcji. Subskrybując, upoważniasz nas do obciążenia wybranej metody płatności za pośrednictwem Stripe, naszego bezpiecznego partnera płatniczego. Opłaty subskrypcyjne są wyświetlane na naszej stronie Cennik, są przetwarzane automatycznie zgodnie z cyklem rozliczeniowym i mogą być odnawiane co miesiąc lub co rok do momentu anulowania. O ile prawo nie stanowi inaczej, opłaty subskrypcyjne nie podlegają zwrotowi po naliczeniu, chociaż w wyjątkowych przypadkach, takich jak duplikaty płatności lub błędy systemowe, można skontaktować się z pomocą techniczną w celu uzyskania pomocy. Bezpłatny okres próbny, jeśli zostanie zapewniony, będzie ograniczony do wskazanego czasu trwania.",
      "All content, features, AI-generated outputs, and visuals on MANIFEX belong to the company and are protected by intellectual property rights. You are granted a limited, non-exclusive license to use this content for personal learning purposes and you may not copy, sell, or distribute materials without written permission. Some activities allow you to create your own text, such as in Smart Writing practice. You retain ownership of your written content, but by submitting it you grant MANIFEX limited rights to analyze, process, and use the text to improve our services.":
          "Wszystkie treści, funkcje, wyniki generowane przez AI i wizualizacje w MANIFEX należą do firmy i są chronione prawami własności intelektualnej. Otrzymujesz ograniczoną, niewyłączną licencję na korzystanie z tych treści do osobistych celów edukacyjnych i nie możesz kopiować, sprzedawać ani rozpowszechniać materiałów bez pisemnej zgody. Niektóre działania pozwalają na tworzenie własnych tekstów, np. w ramach ćwiczeń Smart Writing. Zachowujesz własność swoich treści pisemnych, ale przesyłając je, przyznajesz MANIFEX ograniczone prawa do analizowania, przetwarzania i wykorzystywania tekstu w celu ulepszania naszych usług.",
      "We may suspend or terminate accounts that violate these Terms. You may close your account at any time. While we strive to provide accessible and effective services, MANIFEX is provided “as is” and “as available.” We do not guarantee uninterrupted, error-free, or perfectly accurate service, as AI-based recommendations are intended as guidance and not absolute advice. To the maximum extent permitted by law, MANIFEX and its affiliates will not be liable for indirect or incidental damages resulting from use of the Service. Our total liability shall not exceed the subscription fee paid in the last three months.":
          "Możemy zawiesić lub usunąć konta, które naruszają niniejszy Regulamin. Możesz zamknąć swoje konto w dowolnym momencie. Chociaż staramy się zapewniać dostępne i skuteczne usługi, MANIFEX jest dostarczany w stanie „takim, jakim jest” i „w miarę dostępności”. Nie gwarantujemy nieprzerwanego, wolnego od błędów lub idealnie dokładnego działania serwisu, ponieważ rekomendacje oparte na sztucznej inteligencji są przeznaczone jako wskazówki, a nie porady absolutne. W maksymalnym zakresie dozwolonym przez prawo, MANIFEX i jego podmioty stowarzyszone nie ponoszą odpowiedzialności za szkody pośrednie lub przypadkowe wynikające z korzystania z Serwisu. Nasza całkowita odpowiedzialność nie przekroczy opłaty subskrypcyjnej zapłaconej w ciągu ostatnich trzech miesięcy.",
      "We reserve the right to update or modify these Terms and the platform itself at any time. Continued use after updates indicates acceptance of the new Terms. Your use of the Service also means you agree to our Privacy Policy, which explains how we handle your personal information.":
          "Zastrzegamy sobie prawo do aktualizacji lub zmiany niniejszego Regulaminu oraz samej platformy w dowolnym momencie. Dalsze korzystanie z Serwisu po wprowadzeniu aktualizacji oznacza akceptację nowego Regulaminu. Korzystanie z Serwisu oznacza również zgodę na naszą Politykę Prywatności, która wyjaśnia, w jaki sposób obchodzimy się z Twoimi danymi osobowymi.",
      "These Terms will be governed by and interpreted under the laws of [Insert Country/Region], with disputes handled exclusively by the courts of [Insert Location]. If you have questions about these Terms, you can contact us at [support@manifex.org] or at our business address.":
          "Niniejszy Regulamin podlega prawu [Wstaw Kraj/Region] i będzie zgodnie z nim interpretowany, a spory będą rozstrzygane wyłącznie przez sądy w [Wstaw Lokalizację]. Jeśli masz pytania dotyczące niniejszego Regulaminu, możesz skontaktować się z nami pod adresem [support@manifex.org] lub pod adresem naszej firmy.",
      "By accessing or using MANIFEX, you acknowledge that you have read, understood, and agreed to these Terms of Use.":
          "Uzyskując dostęp do MANIFEX lub korzystając z niego, potwierdzasz, że przeczytałeś, zrozumiałeś i zgodziłeś się na niniejszy Regulamin Korzystania.",
