      "Next": "পরবর্তী",
      "Track your growth": "আপনার অগ্রগতি ট্র্যাক করুন",
      "See how your mindset evolves over time with clear insights.":
          "স্পষ্ট অন্তর্দৃষ্টির মাধ্যমে দেখুন কীভাবে সময়ের সাথে আপনার মানসিকতা বিকশিত হচ্ছে।",
      "Please select your language": "অনুগ্রহ করে আপনার ভাষা নির্বাচন করুন",
