      "Write. Learn. Improve. AI checks your grammar, structure, and style instantly.":
          "লিখুন। শিখুন। উন্নতি করুন। এআই তাৎক্ষণিকভাবে আপনার ব্যাকরণ, গঠন এবং শৈলী যাচাই করে।",
