      "Connect education with personal interests for maximum engagement":
          "সর্বাধিক ব্যস্ততার জন্য ব্যক্তিগত আগ্রহের সাথে শিক্ষাকে সংযুক্ত করুন",
      "100,000+ Learners": "১০০,০০০+ শিক্ষার্থী",
      "Positive Rating": "ইতিবাচক রেটিং",
      "AI Support": "এআই সাপোর্ট",
      "At the Core of Our Approach are":
          "আমাদের পদ্ধতির একেবারে কেন্দ্রে রয়েছে",
      "4 Key Foundations": "৪টি মূল ভিত্তি",
      "1. Neuroplasticity": "১. নিউরোপ্লাস্টিসিটি",
      "The brain has an incredible ability to reorganize itself by forming new neural connections throughout life. This process not only supports learning and problem-solving but also helps individuals adapt to new challenges. Our activities are designed to activate neuroplasticity, making practice more impactful over time.":
          "সারাজীবন নতুন নিউরাল সংযোগ তৈরি করে নিজেকে পুনর্গঠিত করার ব্রেনের একটি অবিশ্বাস্য ক্ষমতা রয়েছে। এই প্রক্রিয়াটি কেবল শেখা এবং সমস্যা সমাধানে সাহায্য করে না বরং ব্যক্তিদের নতুন চ্যালেঞ্জগুলির সাথে মানিয়ে নিতেও সহায়তা করে। আমাদের ক্রিয়াকলাপগুলি নিউরোপ্লাস্টিসিটি সক্রিয় করার জন্য ডিজাইন করা হয়েছে, যা অনুশীলনকে সময়ের সাথে সাথে আরও প্রভাবশালী করে তোলে।",
      "2. Rhythmic Therapy": "২. রিদমিক থেরাপি",
      "Humans are naturally responsive to rhythm. By using rhythmic and repetitive patterns, we help regulate the brain and nervous system. Here, we use music to rhythmically influence the reshaping of neurons and their plasticity by creating new neuronic pathways when working on our activities.This fortifies retention and facilitates the application of newly learned behaviors when using cognitive processing. This approach can reduce stress, improve focus, and create a natural flow in reading, writing, and speaking.":
          "মানুষ স্বাভাবিকভাবেই ছন্দের প্রতি প্রতিক্রিয়াশীল। ছন্দময় এবং পুনরাবৃত্তিমূলক ধরণগুলির সাহায্যে, আমরা ব্রেন এবং স্নায়ুতন্ত্র নিয়ন্ত্রণে সাহায্য করি। এখানে, আমরা আমাদের ক্রিয়াকলাপের সময় নতুন নিউরনিক পথ তৈরি করে নিউরনগুলির পুনর্গঠন এবং তাদের প্লাস্টিসিটিকে ছন্দময়ভাবে প্রভাবিত করতে সঙ্গীত ব্যবহার করি। এটি স্মরণশক্তি বজায় রাখতে সাহায্য করে এবং জ্ঞানীয় প্রক্রিয়াকরণ ব্যবহার করার সময় নতুন শেখা আচরণ প্রয়োগ সহজ করে। এই পদ্ধতি চাপ কমাতে, ফোকাস উন্নত করতে এবং পড়া, লেখা এবং কথা বলার ক্ষেত্রে একটি স্বাভাবিক প্রবাহ তৈরি করতে সহায়তা করতে পারে।",
      "3. Dysgraphia Support": "৩. ডিসগ্রাফিয়া সাপোর্ট",
      "Dysgraphia is a neurological condition that affects writing. Our tools offer structured practice to strengthen handwriting, written expression, and the motor skills that support the writing process.":
          "ডিসগ্রাফিয়া একটি স্নায়বিক অবস্থা যা লেখাকে প্রভাবিত করে। আমাদের টুলগুলো হাতের লেখা, লিখিত প্রকাশ এবং লেখার প্রক্রিয়াকে সমর্থনকারী মোটর দক্ষতা শক্তিশালী করার জন্য কাঠামোগত অনুশীলনের সুযোগ দেয়।",
      "4. Dyslexia Support": "৪. ডিসলেক্সিয়া সাপোর্ট",
      "Dyslexia, a neurobiological learning difference, can make reading, writing, and spelling difficult. We provide engaging activities that build fluency, comprehension, and language skills—helping learners overcome barriers with confidence.":
          "ডিসলেক্সিয়া, একটি নিউরোবায়োলজিকাল শেখার পার্থক্য, পড়া, লেখা এবং বানান করা কঠিন করে তুলতে পারে। আমরা সাবলীলতা, বোঝাপড়া এবং ভাষার দক্ষতা তৈরি করে এমন আকর্ষণীয় কার্যকলাপ প্রদান করি—শিক্ষার্থীদের আত্মবিশ্বাসের সাথে বাধা অতিক্রম করতে সাহায্য করে।",
      "Last Updated: January 21, 2026": "সর্বশেষ আপডেট: জানুয়ারি ২১, ২০২৬",
      "At MANIFEX, we respect and value your privacy. This Privacy Policy explains how we collect, use, and protect your personal information when you visit our website or use our services. By accessing MANIFEX, you agree to the practices described in this policy. If you do not agree, please discontinue using our services.":
          "MANIFEX-এ আমরা আপনার গোপনীয়তাকে সম্মান করি এবং মূল্য দিই। আপনি যখন আমাদের ওয়েবসাইট পরিদর্শন করেন বা আমাদের পরিষেবা ব্যবহার করেন তখন আমরা কীভাবে আপনার ব্যক্তিগত তথ্য সংগ্রহ করি, ব্যবহার করি এবং সুরক্ষিত করি তা এই গোপনীয়তা নীতি ব্যাখ্যা করে। MANIFEX অ্যাক্সেস করার মাধ্যমে, আপনি এই নীতিতে বর্ণিত অনুশীলনগুলিতে সম্মত হন। আপনি যদি একমত না হন, অনুগ্রহ করে আমাদের পরিষেবা ব্যবহার করা বন্ধ করুন।",
      "When you create an account or use MANIFEX, we may collect certain personal information such as your name, email address, age group, language preference, subscription details, and any content you submit during practice activities such as writing exercises. For minors, we may also collect guardian or parent contact details for verification and progress tracking. In addition, we automatically collect certain technical information such as your browser type, device, IP address, and usage activity to ensure smooth functionality and improve the user experience.":
          "আপনি যখন একটি অ্যাকাউন্ট তৈরি করেন বা MANIFEX ব্যবহার করেন, তখন আমরা আপনার নাম, ইমেল ঠিকানা, বয়স, ভাষার পছন্দ, সাবস্ক্রিপশনের বিবরণ এবং লেখার অনুশীলনের মতো অনুশীলনমূলক কার্যকলাপের সময় আপনার জমা দেওয়া যেকোনো বিষয়বস্তুর মতো নির্দিষ্ট ব্যক্তিগত তথ্য সংগ্রহ করতে পারি। অপ্রাপ্তবয়স্কদের জন্য, আমরা যাচাইকরণ এবং অগ্রগতি ট্র্যাক করার জন্য অভিভাবক বা পিতামাতার যোগাযোগের বিবরণও সংগ্রহ করতে পারি। এছাড়াও, আমাদের মসৃণ কার্যকারিতা নিশ্চিত করতে এবং ব্যবহারকারীর অভিজ্ঞতা উন্নত করতে আপনার ব্রাউজারের ধরন, ডিভাইস, আইপি ঠিকানা এবং ব্যবহারের কার্যকলাপের মতো নির্দিষ্ট প্রযুক্তিগত তথ্য স্বয়ংক্রিয়ভাবে সংগ্রহ করি।",
      "We use the information we collect to deliver and personalize our services, provide AI-powered feedback, provide subscription payments securely through Stripe, track progress and generate analytics, send user updates or notifications, and improve MANIFEX by analyzing learner behaviors and preferences. Your personal data is used solely for the purpose of operating and enhancing the platform. We never sell your data to third parties.":
          "আমরা আমাদের পরিষেবাগুলি সরবরাহ এবং ব্যক্তিগতকৃত করতে, এআই-চালিত প্রতিক্রিয়া প্রদান করতে, স্ট্রাইপের মাধ্যমে নিরাপদে সাবস্ক্রিপশন প্রদান করতে, অগ্রগতি ট্র্যাক করতে এবং বিশ্লেষণ তৈরি করতে, ব্যবহারকারীদের আপডেট বা সতর্কতা প্রেরণে এবং শিক্ষার্থীদের আচরণ ও পছন্দগুলি বিশ্লেষণ করে MANIFEX উন্নত করতে সংগ্রহ করা তথ্য ব্যবহার করি। আপনার ব্যক্তিগত ডেটা শুধুমাত্র প্ল্যাটফর্ম পরিচালনা এবং উন্নত করার উদ্দেশ্যে ব্যবহার করা হয়। আমরা কখনো তৃতীয় পক্ষের কাছে আপনার ডেটা বিক্রি করি না।",
      "MANIFEX uses trusted third-party tools and services, such as Stripe for payment processing. Stripe collects and processes payment information on our behalf, and we do not store your full payment card details on our servers. Integrations with third-party providers are carefully selected, and we require them to follow strict security and privacy practices.":
          "MANIFEX পেমেন্ট প্রক্রিয়াকরণের জন্য স্ট্রাইপ-এর মতো বিশ্বস্ত তৃতীয় পক্ষের সরঞ্জাম এবং পরিষেবা ব্যবহার করে। স্ট্রাইপ আমাদের পক্ষ থেকে অর্থপ্রদানের তথ্য সংগ্রহ এবং প্রক্রিয়া করে এবং আমরা আমাদের সার্ভারে আপনার সম্পূর্ণ পেমেন্ট কার্ডের বিবরণ সংরক্ষণ করি না। তৃতীয় পক্ষের প্রদানকারীদের সাথে সংযোগ সতর্কতার সাথে নির্বাচন করা হয় এবং আমরা তাদের কঠোর সুরক্ষা এবং গোপনীয়তা অনুশীলন অনুসরণ করার দাবি জানাই।",
      "We take the security of your information seriously. All data is protected using industry-standard encryption and secure storage practices. Access to personal data is restricted to authorized team members only, and we routinely monitor and update our systems to prevent unauthorized access, loss, misuse, or disclosure. However, no system can ever be 100% secure, and we cannot guarantee absolute protection of your information.":
          "আমরা আপনার তথ্যের সুরক্ষাকে গুরুত্ব সহকারে দেখি। সমস্ত ডেটা শিল্প-মান এনক্রিপশন এবং নিরাপদ স্টোরেজ অনুশীলনের মাধ্যমে সুরক্ষিত। ব্যক্তিগত ডেটাতে অ্যাক্সেস শুধুমাত্র অনুমোদিত দলের সদস্যদের জন্য সীমাবদ্ধ, এবং আমরা অননুমোদিত অ্যাক্সেস, ক্ষতি, অপব্যবহার বা প্রকাশ রোধ করতে নিয়মিত আমাদের সিস্টেমগুলি পর্যবেক্ষণ ও আপডেট করি। তবে, কোনো সিস্টেম ১০০% সুরক্ষিত হতে পারে না এবং আমরা আপনার তথ্যের সম্পূর্ণ সুরক্ষার নিশ্চয়তা দিতে পারি না।",
      "If you are a child or minor, guardian or parent consent may be required to create an account and access certain features. Parent dashboards and notifications may be used to update guardians about a child’s learning progress.":
          "আপনি যদি শিশু বা নাবালক হন, অ্যাকাউন্ট তৈরি করতে এবং নির্দিষ্ট বৈশিষ্ট্যগুলি অ্যাক্সেস করতে অভিভাবক বা পিতামাতার সম্মতির প্রয়োজন হতে পারে। একটি শিশুর শেখার অগ্রগতি সম্পর্কে অভিভাবকদের আপডেট করতে প্যারেন্ট ড্যাশবোর্ড এবং নোটিফিকেশন ব্যবহার করা হতে পারে।",
      "You have certain rights regarding your personal information. At any time, you may access your account, update or correct your details, or request account deletion. If you cancel your subscription or deactivate your account, some data may remain in backup storage or logs but will not be used further. To exercise these rights, please contact us at the provided email address.":
          "আপনার ব্যক্তিগত তথ্য সম্পর্কে আপনার নির্দিষ্ট অধিকার রয়েছে। যে কোনো সময়, আপনি আপনার অ্যাকাউন্ট অ্যাক্সেসঁয় করতে পারেন, আপনার বিবরণ আপডেট বা সংশোধন করতে পারেন, বা অ্যাকাউন্ট মুছে ফেলার অনুরোধ করতে পারেন। যদি আপনি আপনার সাবস্ক্রিপশন বাতিল করেন বা আপনার অ্যাকাউন্ট নিষ্ক্রিয় করেন, কিছু ডেটা ব্যাকআপ স্টোরেজ বা লগগুলিতে থাকতে পারে তবে আর ব্যবহার করা হবে না। এই অধিকারগুলি অনুশীলন করতে, অনুগ্রহ করে প্রদত্ত ইমেল ঠিকানায় আমাদের সাথে যোগাযোগ করুন।",
      "Our services are not designed to collect sensitive personal data such as racial or ethnic origin, political opinions, religious beliefs, or health-related details. Please do not provide this information when using our platform.":
          "আমাদের পরিষেবাগুলি জাতিগত বা জাতিগত গোষ্ঠী, রাজনৈতিক মতামত, ধর্মীয় বিশ্বাস, বা স্বাস্থ্য সম্পর্কিত বিবরণের মতো সংবেদনশীল ব্যক্তিগত ডেটা সংগ্রহ করার উদ্দেশ্যে নয়। অনুগ্রহ করে আমাদের প্ল্যাটফর্ম ব্যবহার করার সময় এই তথ্য প্রদান করবেন না।",
      "We may update this Privacy Policy from time to time to reflect new features, technologies, or legal requirements. If there are significant changes, we will notify you via email or through the platform. By continuing to use MANIFEX after those updates, you agree to the revised Privacy Policy.":
          "নতুন বৈশিষ্ট্য, প্রযুক্তি বা আইনি প্রয়োজনীয়তা প্রতিফলিত করতে আমরা সময়ে সময়ে এই গোপনীয়তা নীতি আপডেট করতে পারি। যদি উল্লেখযোগ্য পরিবর্তন হয়, আমরা ইমেল বা প্ল্যাটফর্মের মাধ্যমে আপনাকে অবহিত করব। সেই পরিবর্তনের পরে MANIFEX ব্যবহার চালিয়ে যাওয়ার মাধ্যমে আপনি সংশোধিত গোপনীয়তা নীতির সাথে একমত হবেন।",
      "This Privacy Policy is governed by the laws of [Insert Country/Region]. Any disputes will be resolved in the courts of [Insert Location].":
          "এই গোপনীয়তা নীতি [Insert Country/Region]-এর আইন দ্বারা পরিচালিত হয়। যেকোনো বিরোধ [Insert Location]-এর আদালতে মীমাংসা করা হবে।",
      "If you have any questions, concerns, or complaints about how we handle your personal data, please reach out to us at:\nEmail: [support@manifex.org]\nAddress: [Insert Business Address]":
          "আমরা কীভাবে আপনার ব্যক্তিগত ডেটা পরিচালনা করি তা নিয়ে আপনার কোনো প্রশ্ন, উদ্বেগ বা অভিযোগ থাকলে, অনুগ্রহ করে আমাদের সাথে এখানে যোগাযোগ করুন:\nইমেইল: [support@manifex.org]\nঠিকানা: [Insert Business Address]",
      "By using MANIFEX, you acknowledge that you have read, understood, and agreed to this Privacy Policy.":
          "MANIFEX ব্যবহার করে, আপনি স্বীকার করছেন যে আপনি এই গোপনীয়তা নীতি পড়েছেন, বুঝেছেন এবং এতে সম্মত হয়েছেন।",
      "Terms of Conditions": "নিয়ম সংবলিত শর্তাবলি",
      "Welcome to MANIFEX. These Terms of Use (“Terms”) govern your access to and use of our platform, website, and services. By using MANIFEX, you agree to follow these Terms. Please read them carefully. If you do not agree, you may not use our Service.":
          "MANIFEX-এ স্বাগতম। এই ব্যবহারের শর্তাবলী (“শর্তাবলী”) আমাদের প্ল্যাটফর্ম, ওয়েবসাইট এবং পরিষেবাগুলিতে আপনার অ্যাক্সেস এবং ব্যবহার পরিচালনা করে। MANIFEX ব্যবহার করার মাধ্যমে, আপনি এই শর্তাবলী অনুসরণ করতে সম্মত হন। অনুগ্রহ করে মনোযোগ দিয়ে এগুলো পড়ুন। আপনি একমত না হলে, আমাদের পরিষেবা ব্যবহার করতে পারবেন না।",
      "MANIFEX is intended for learners of all ages, but you must be at least 13 years old to create an account. If you are under 18, you must have parent or guardian consent to use the platform. By using the Service, you confirm that the information you provide is accurate and truthful. When you create an account, you are responsible for safeguarding your password and account. You should notify us immediately if you suspect unauthorized access. We are not liable for damages or losses resulting from failure to protect your login details.":
          "MANIFEX সব বয়সের শিক্ষার্থীদের জন্য, তবে অ্যাকাউন্ট তৈরি করতে আপনার বয়স অন্তত ১৩ বছর হতে হবে। ১৮ বছরের কম বয়সীদের প্ল্যাটফর্ম ব্যবহারের জন্য অভিভাবক বা পিতামাতার সম্মতি থাকতে হবে। পরিষেবা ব্যবহার করে আপনি নিশ্চিত করেন যে প্রদত্ত তথ্য সঠিক এবং সত্য। অ্যাকাউন্ট তৈরি করার সময় পাসওয়ার্ড এবং অ্যাকাউন্টের সুরক্ষা আপনার দায়িত্ব। অননুমোদিত অ্যাক্সেস সন্দেহ হলে তাৎক্ষণিকভাবে আমাদের জানাবেন। লগইন ডিটেইলস সুরক্ষিত রাখতে ব্যর্থতার কারণে হওয়া ক্ষতি বা লোকসানের জন্য আমরা দায়ী নই।",
      "Our platform is designed to help users practice English reading, writing, and speaking through AI-powered support. You agree to use the Service only for learning purposes in a lawful way. Misuse, such as attempting unauthorized access, copying or redistributing content without permission, uploading inappropriate, offensive or illegal material, or disrupting service operations, is prohibited.":
          "আমাদের প্ল্যাটফর্মটি এআই-চালিত সহায়তার মাধ্যমে ব্যবহারকারীদের ইংরেজি পড়া, লেখা এবং কথা বলার অনুশীলনে সহায়তা করতে ডিজাইন করা হয়েছে। আপনি এই পরিষেবাটি কেবল আইনসম্মত উপায়ে শিক্ষার উদ্দেশ্যে ব্যবহার করতে সম্মত হন। অপব্যবহার, যেমন অননুমোদিত অ্যাক্সেসের চেষ্টা করা, অনুমতি ছাড়া বিষয়বস্তু কপি বা বিতরণ করা, অনুপযুক্ত, আপত্তিকর বা অবৈধ উপকরণ আপলোড করা, বা পরিষেবা কার্যক্রমে বিঘ্ন ঘটানো নিষিদ্ধ।",
      "Certain features of MANIFEX require a paid subscription. By subscribing, you authorize us to charge your selected payment method through Stripe, our secure payment partner. Subscription fees are displayed on our Pricing page, processed automatically according to your billing cycle, and may renew monthly or annually until canceled. Unless required by law, subscription fees are non-refundable once charged, though in exceptional cases such as duplicate payments or system errors you may contact support for assistance. A free trial, if provided, will be limited to the duration stated.":
          "MANIFEX-এর কিছু বৈশিষ্ট্যে একটি পেইড সাবস্ক্রিপশন প্রয়োজন। সাবস্ক্রাইব করার মাধ্যমে, আপনি আমাদের সুরক্ষিত পেমেন্ট পার্টনার, স্ট্রাইপ-এর মাধ্যমে আপনার নির্বাচিত পদ্ধতিতে চার্জ করার অনুমতি দেন। সাবস্ক্রিপশন ফি আমাদের মূল্যের পৃষ্ঠায় দেখানো হয়, যা বিলিং চক্র অনুযায়ী স্বয়ংক্রিয়ভাবে প্রক্রিয়া করা হয় এবং তা বাতিল হওয়ার আগে পর্যন্ত মাসিক বা বার্ষিক রিনিউ হতে পারে। আইন অনুযায়ী নির্দিষ্ট না হওয়া পর্যন্ত, একবার চার্জ করার পরে সাবস্ক্রিপশন ফি ফেরতযোগ্য নয়, তবে ডাবল পেমেন্ট বা সিস্টেম ত্রুটির মতো বিশেষ ক্ষেত্রে সহায়তার জন্য সাপোর্টে যোগাযোগ করতে পারেন। যদি ফ্রি ট্রায়াল প্রদান করা হয় তবে তা নির্দিষ্ট সময়ের জন্য সীমাবদ্ধ থাকবে।",
      "All content, features, AI-generated outputs, and visuals on MANIFEX belong to the company and are protected by intellectual property rights. You are granted a limited, non-exclusive license to use this content for personal learning purposes and you may not copy, sell, or distribute materials without written permission. Some activities allow you to create your own text, such as in Smart Writing practice. You retain ownership of your written content, but by submitting it you grant MANIFEX limited rights to analyze, process, and use the text to improve our services.":
          "MANIFEX-এর সমস্ত সামগ্রী, বৈশিষ্ট্য, এআই-জেনারেটেড আউটপুট এবং ভিজ্যুয়াল কোম্পানির অন্তর্ভুক্ত এবং মেধা সম্পত্তি রাইটস দ্বারা সুরক্ষিত। ব্যক্তিগত শিক্ষার উদ্দেশ্যে ব্যবহার করার জন্য আপনাকে একটি সীমিত এবং অ-একচেটিয়া লাইসেন্স দেওয়া হয় এবং আপনি লিখিত অনুমতি ছাড়া সামগ্রী কপি, বিক্রি বা বিতরণ করতে পারবেন না। স্মার্ট রাইটিং অনুশীলনের মতো বেশকয়েকটি কাজে আপনি আপনার নিজের পাঠ্য তৈরি করতে পারবেন। আপনার লিখিত উপাদানের মালিকানা আপনারই থাকবে, তবে এটি জমা দিলে আপনি আমাদের পরিষেবার উন্নতির জন্য পাঠ্য বিশ্লেষণ, প্রক্রিয়া এবং ব্যবহার করার সীমিত অধিকার দেন।",
      "We may suspend or terminate accounts that violate these Terms. You may close your account at any time. While we strive to provide accessible and effective services, MANIFEX is provided “as is” and “as available.” We do not guarantee uninterrupted, error-free, or perfectly accurate service, as AI-based recommendations are intended as guidance and not absolute advice. To the maximum extent permitted by law, MANIFEX and its affiliates will not be liable for indirect or incidental damages resulting from use of the Service. Our total liability shall not exceed the subscription fee paid in the last three months.":
          "এই শর্তাবলী লঙ্ঘনকারী অ্যাকাউন্টগুলিকে আমরা সাময়িকভাবে বা স্থায়ীভাবে স্থগিত করতে পারি। আপনি যেকোনো সময় আপনার অ্যাকাউন্ট বন্ধ করতে পারেন। যদিও আমরা অ্যাক্সেসযোগ্য এবং কার্যকর পরিষেবা প্রদানের চেষ্টা করি, MANIFEX “যেভাবে আছে” এবং “যথাবিধি উপলব্ধ” অবস্থায় প্রদান করা হয়। আমরা অবিচ্ছিন্ন, ত্রুটিমুক্ত, অথবা একেবারে নিখুঁত পরিষেবার গ্যারান্টি দিই না, যেহেতু এআই-ভিত্তিক সুপারিশগুলি নির্দেশিকা হিসেবে বিবেচিত হয় বরং একেবারে পরামর্শ হিসেবে নয়। আইনের দ্বারা সর্বোচ্চ অনুমোদিত সীমা পর্যন্ত, MANIFEX এবং এর সহযোগী সংস্থাগুলি এই পরিষেবা ব্যবহারের ফলে উদ্ভূত কোনো প্রচ্ছন্ন বা পরোক্ষ ক্ষতির জন্য দায়ী হবে না। আমাদের সামগ্রিক দায়বদ্ধতা গত তিন মাসে প্রদত্ত সাবস্ক্রিপশন ফির বেশি হবে না।",
      "We reserve the right to update or modify these Terms and the platform itself at any time. Continued use after updates indicates acceptance of the new Terms. Your use of the Service also means you agree to our Privacy Policy, which explains how we handle your personal information.":
          "আমরা যেকোনো সময় এই শর্তাবলী এবং প্ল্যাটফর্ম আপডেট বা সংশোধন করার অধিকার সংরক্ষণ করি। আপডেটের পর ক্রমাগত ব্যবহার নতুন শর্তগুলির সম্মতি নির্দেশ করে। আপনাদের পরিষেবা ব্যবহারে আমাদের গোপনীয়তা নীতিমালার সাথে আপনার সম্মতিও অন্তর্ভুক্ত থাকে, যেখানে আমরা আপনার ব্যক্তিগত তথ্য কীভাবে ব্যবহার ও সংরক্ষণ করি তা বিশদভাবে বর্ণনা করে।",
      "These Terms will be governed by and interpreted under the laws of [Insert Country/Region], with disputes handled exclusively by the courts of [Insert Location]. If you have questions about these Terms, you can contact us at [support@manifex.org] or at our business address.":
          "এই শর্তাবলী [Insert Country/Region]-এর আইনের আওতায় পরিচালিত ও ব্যাখ্যা করা হবে, এবং বিবাদের নিষ্পত্তি শুধুমাত্র [Insert Location]-এর আদালত দ্বারা বিবেচনা করা হবে। যদি এই শর্তাবলী নিয়ে আপনার কোনো প্রশ্ন থাকে, তবে আমাদের সাথে [support@manifex.org] অথবা আমাদের ব্যবসায়ের ঠিকানায় যোগাযোগ করতে পারেন।",
