    'hi_IN': {
      "Welcome to MANIFEX! Let’s start your language learning journey today":
          "MANIFEX में आपका स्वागत है! आइए आज अपनी भाषा सीखने की यात्रा शुरू करें",
      "Set your intention": "अपना इरादा तय करें",
      "Define what truly matters to you every single day.":
          "परिभाषित करें कि आपके लिए हर दिन वास्तव में क्या मायने रखता है।",
      "Train your mindset": "अपनी मानसिकता को प्रशिक्षित करें",
      "Strengthen focus, discipline, and self-belief with consistency.":
          "निरंतरता के साथ ध्यान, अनुशासन और आत्मविश्वास को मजबूत करें।",
      "Next": "अगला",
      "Track your growth": "अपनी वृद्धि को ट्रैक करें",
      "See how your mindset evolves over time with clear insights.":
          "स्पष्ट अंतर्दृष्टि के साथ देखें कि समय के साथ आपकी मानसिकता कैसे विकसित होती है।",
      "Please select your language": "कृपया अपनी भाषा चुनें",
      "Email": "ईमेल",
